"""Notification log and cash-related events. Operates on the depot's state dict."""


def emit(st, *args):
    st["notes"].append(list(args))


def check_cash(st):
    """Emit OVERDRAWN when cash crosses below 0 (once per crossing)."""
    if st["cash"] < 0:
        if not st["overdrawn"]:
            st["overdrawn"] = True
            emit(st, "OVERDRAWN")
    else:
        st["overdrawn"] = False
