"""Seeded demand simulation (C29)."""
import random

import money


def simulate(days, seed):
    demand = money.load_data()["demand"]
    rng = random.Random(seed)
    result = []
    for _ in range(days):
        orders = []
        for sku in sorted(demand):
            qty = rng.randint(demand[sku]["min"], demand[sku]["max"])
            if qty > 0:
                orders.append((sku, qty))
        result.append(orders)
    return result
